'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict');
const css=fs.readFileSync('assets/arcade-candy-world-v157.css','utf8');
const all=fs.readFileSync('assets/all-tabs-v150.css','utf8');
const menu=fs.readFileSync('assets/game-menu-v91.js','utf8');
const version=JSON.parse(fs.readFileSync('app-version.json','utf8')).version;
const selector='html.arcade-candy-world-v157[data-lineup="all"] #tabs>.tab-slot>.all-tab-frame-overlay';
const start=css.indexOf(selector);
assert(start>=0,'nine-tab decorated overlay exists');
const block=css.slice(start,css.indexOf('}',start));
assert(block.includes('z-index:1!important'),'ornamental overlay must sit below game content');
assert(!block.includes('z-index:80!important'),'opaque overlay cannot hide live tabs');
assert(block.includes('background:var(--all-tab-frame)'),'generated game-specific frames retained');
assert.equal((all.match(/--all-tab-frame:url/g)||[]).length,9,'all nine game frames exist');
assert(all.includes('z-index:30!important'),'live preview above decoration');
assert(all.includes('z-index:40!important'),'BET and reach above decoration');
assert(menu.includes('arcade-candy-world-v157.css?v=233'),'mobile CSS cache must be busted');
assert(Number(version.match(/-v(\d+)-/)?.[1])>=233,'installed clients must receive the frame fix');
console.log('NINE_TAB_VISIBILITY_V233_PASS');
